import sympy

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def has_roots_mod_p(f, p):
    # Compute the polynomial f(x) mod p
    f_mod_p = f.subs(sympy.symbols('x'), sympy.symbols('x', mod=p))

    # Check if f_mod_p has roots mod p
    return sympy.solve(f_mod_p, sympy.symbols('x'))!= []

# Define the polynomial f(x) = x^2 + 3x + 3
f = sympy.sympify('x**2 + 3*x + 3')

# Check for roots mod p for odd primes p > 3
for p in range(7, 100, 2):  # Start from 7, the first odd prime > 3
    if is_prime(p):
        if has_roots_mod_p(f, p):
            print(f'p = {p} has roots mod p')
        else:
            print(f'p = {p} does not have roots mod p')
        print()
